theory.code:
List<Product> products = List.of(
        new Product("Laptop", 3499.0),
        new Product("Mysz", 49.9));

assertThat(products)
        .extracting(Product::name)
        .containsExactly("Laptop", "Mysz");

assertThat(products)
        .extracting(Product::name, Product::price)
        .contains(tuple("Mysz", 49.9));
